(async () => {
  const { env } = await import('node:process');
  const { accessSync, constants } = await import('node:fs');
  const inputPath = env.INPUT_PATH;
  const outputPath = env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  try { accessSync(inputPath, constants.R_OK); } catch { throw new Error('Input file not accessible'); }
  globalThis.inputPath = inputPath;
  globalThis.outputPath = outputPath;
})();

(async () => {
  const { createReadStream, writeFileSync } = await import('node:fs');
  const { pipeline } = await import('node:stream/promises');
  const { Writable } = await import('node:stream');
  const { Yaml2json } = await import('@adius/yaml2json');
  const inputPath = globalThis.inputPath;
  const outputPath = globalThis.outputPath;
  let result = '';
  const collector = new Writable({
    write(chunk, _enc, cb) { result += chunk.toString(); cb(); }
  });
  await pipeline(createReadStream(inputPath), new Yaml2json(), collector);
  writeFileSync(outputPath, result);
  globalThis.resultPath = outputPath;
})();

(async () => {
  const outputPath = globalThis.resultPath;
  if (!outputPath) throw new Error('Result path not set');
  console.log(JSON.stringify({ output_path: outputPath }));
})();
